import{_ as a,H as e,f as n,i as l}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"08 | 渐进披露：按需调阅关键上下文","description":"","frontmatter":{},"headers":[{"level":2,"title":"一项 Skill 变长以后，为什么不能一次全部装入 Context？","slug":"一项-skill-变长以后-为什么不能一次全部装入-context","link":"#一项-skill-变长以后-为什么不能一次全部装入-context","children":[]},{"level":2,"title":"渐进披露怎样借助 Agent Loop 发生？","slug":"渐进披露怎样借助-agent-loop-发生","link":"#渐进披露怎样借助-agent-loop-发生","children":[]},{"level":2,"title":"Harness 怎样把 Skill 接入这条 Loop？","slug":"harness-怎样把-skill-接入这条-loop","link":"#harness-怎样把-skill-接入这条-loop","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"课后题","slug":"课后题","link":"#课后题","children":[{"level":3,"title":"观察题：一项 Skill 的三层内容何时出现？","slug":"观察题-一项-skill-的三层内容何时出现","link":"#观察题-一项-skill-的三层内容何时出现","children":[]},{"level":3,"title":"思考题：不用 Skill，只用 MCP，能否重做出同样的渐进披露？","slug":"思考题-不用-skill-只用-mcp-能否重做出同样的渐进披露","link":"#思考题-不用-skill-只用-mcp-能否重做出同样的渐进披露","children":[]}]}],"relativePath":"自进化Agent工程实战/08｜渐进披露：按需调阅关键上下文.md","filePath":"自进化Agent工程实战/08｜渐进披露：按需调阅关键上下文.md","lastUpdated":1795559729000}'),p={name:"自进化Agent工程实战/08｜渐进披露：按需调阅关键上下文.md"};function t(i,s,o,c,d,r){return e(),n("div",null,[...s[0]||(s[0]=[l(`<h1 id="_08-渐进披露-按需调阅关键上下文" tabindex="-1">08 | 渐进披露：按需调阅关键上下文 <a class="header-anchor" href="#_08-渐进披露-按需调阅关键上下文" aria-label="Permalink to &quot;08 | 渐进披露：按需调阅关键上下文&quot;">​</a></h1><p>你好，我是 Tyler。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>项目刚开始时，AGENTS.md 里只有几条规则，Skill 也只有一个。随着经验积累，事故手册、</span></span></code></pre></div><p>日志字段、报告模板和检查脚本越来越多。把它们全部交给模型看似省事，但模型每次工作前，都得先从大量无关内容里找出眼前需要的一小部分。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>比如上一讲，我们让 Codex 从历史支付模块的一次成功调查中生成了 legacy-payment-</span></span>
<span class="line"><span>oncall Skill。当这项 Skill 继续变长，Agent 怎么才能按需要调阅它当前最需要的信息呢？</span></span></code></pre></div><h2 id="一项-skill-变长以后-为什么不能一次全部装入-context" tabindex="-1">一项 Skill 变长以后，为什么不能一次全部装入 Context？ <a class="header-anchor" href="#一项-skill-变长以后-为什么不能一次全部装入-context" aria-label="Permalink to &quot;一项 Skill 变长以后，为什么不能一次全部装入 Context？&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>最初的 legacy-payment-oncall 只有一份很短的 SKILL.md。它记录了发布记录、应用</span></span></code></pre></div><p>日志、连接池和运行配置四个查询入口，以及一条已经验证过的调查顺序：先确认告警范围、取得异常请求的编号，再沿该编号对齐应用日志、实例版本和依赖调用，接着核对发布、指标和当前配置。</p><p>历史模块使用的日志字段很特殊，需要一份字段对照表；事故报告必须引用日志、指标和配置位置，需要一份报告模板；报告写完以后，还要运行脚本检查引用是否完整。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果把这些内容继续写进 SKILL.md，目录看起来仍然很简单，代价却会出现在每次调用</span></span></code></pre></div><p>中。Agent 一旦使用这项 Skill，完整正文就会进入 Context。即使这次告警尚未走到日志分析，字段表已经跟着进来了；报告还没有开始写，模板和检查说明已经先占去了相当一部分Context。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>不把完整方法写进 AGENTS.md、而是放进 Skill，只解决了第一层问题：与这套模块无关的任</span></span></code></pre></div><p>务不再长期携带它。</p><p>要让同一项 Skill 内部的细节也按需出现，我们还得继续拆分，像下面这样。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>legacy-payment-oncall/</span></span>
<span class="line"><span>├── SKILL.md</span></span>
<span class="line"><span>├── references/</span></span>
<span class="line"><span>│   └── log-fields.md</span></span>
<span class="line"><span>├── assets/</span></span>
<span class="line"><span>│   └── incident-report.md</span></span>
<span class="line"><span>└── scripts/</span></span>
<span class="line"><span>   └── check_report.py</span></span>
<span class="line"><span>SKILL.md 只保留主干步骤，并写清什么时候查哪份资料、运行哪个脚本；日志字段说明放</span></span>
<span class="line"><span>进 references/，报告模板放进 assets/，需要重复执行的引用检查放进 scripts/。</span></span></code></pre></div><p>但文件分开存放，并不等于按需加载。我们这就来看看 Agent 调查时怎样逐层取出需要的内容。</p><h2 id="渐进披露怎样借助-agent-loop-发生" tabindex="-1">渐进披露怎样借助 Agent Loop 发生？ <a class="header-anchor" href="#渐进披露怎样借助-agent-loop-发生" aria-label="Permalink to &quot;渐进披露怎样借助 Agent Loop 发生？&quot;">​</a></h2><p>第一讲我们把 Agent 连续工作的过程拆成一条循环：模型根据眼前信息判断下一步，Harness执行动作，再把结果带回后续调用。渐进披露并不需要另搞一套机制：除了任务开始时的能力索引，后面的内容何时出现，仍由这条循环推动。</p><p>巡检开始时，Harness 并不交出每项 Skill 的完整正文，只先提供名称、描述和路径，让模型知道当前有哪些能力可用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这时，legacy-payment-oncall 出现在模型视野中的内容大致如下。</span></span>
<span class="line"><span>name: legacy-payment-oncall</span></span>
<span class="line"><span>description: 调查历史支付模块的超时、错误率和连接异常。需要核对该模块的发布、日志、数据库连接池</span></span>
<span class="line"><span>名称给出这项能力的叫法，description 说明它处理什么问题、何时适用。巡检没有告警</span></span>
<span class="line"><span>时，完整 SKILL.md 仍留在文件系统里。</span></span>
<span class="line"><span>等历史支付模块出现超时，模型看到告警与 Skill 描述，判断能力匹配，便选择 legacy-</span></span>
<span class="line"><span>payment-oncall（你也可以显式输入 $legacy-payment-oncall 直接指定）。Harness</span></span>
<span class="line"><span>随即读取完整 SKILL.md，把调查方法带进接下来的模型输入。</span></span></code></pre></div><p>此时模型知道了主干步骤，却还没看到字段表和报告模板。它先读告警，锁定最早一批异常请</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>求。要从旧格式日志里取出 request_id 时，SKILL.md 提醒它查看 references/log-</span></span>
<span class="line"><span>fields.md，模型提出读取，这一次调用就结束。Harness 打开字段表，带进下一次调用，</span></span>
<span class="line"><span>模型这才认出 request_id 所在字段、取到编号，继续核对发布、数据库指标和当前配置。</span></span>
<span class="line"><span>调查结束、要形成报告时，模型才会读取 assets/incident-report.md；报告写完，再</span></span>
<span class="line"><span>提出运行 scripts/check_report.py，由 Harness 执行并把结果送回下一次调用。模型</span></span></code></pre></div><p>根据执行结果判断哪些结论缺引用、哪些待验证项没标出。</p><p>注意这几次取用都由模型在 Agent Loop 里主动发起：模型不能自己翻阅文件，它提出读取或运行，Harness 才执行，并把结果放进下一次调用；因此什么时候取用，跟着调查进度走，而不是 Harness 预先猜测该塞给模型什么。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>三类资料进入上下文的方式也不相同：references/ 里的字段说明、assets/ 里的报告模</span></span>
<span class="line"><span>板，由模型在相应步骤读取，内容本身进入上下文；scripts/ 里的检查脚本交给 Harness</span></span></code></pre></div><p>执行，回到上下文的只有执行结果，源码并不常驻。</p><p>主干步骤、可读资料、可执行脚本各就其位，模型在哪个阶段，就只拿到那个阶段需要的东</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>西。这也让方法更好维护：字段口径变了只改 references/ 里的对照表，脚本变了只换</span></span>
<span class="line"><span>scripts/，主干 SKILL.md 不必跟着重写。</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/08/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/08/1.png" alt=""></a></p><p>这三层并不是同时、以同一种方式出现：开始时只有名称和描述；描述匹配后模型选择 Skill；完整方法进入 Context 后，模型再沿调查过程判断何时读取资料、使用模板或运行脚本。这就是 Skill 的渐进披露。</p><p>所以渐进披露的运行基础仍然是第一讲的 Agent Loop，只是多了两件 Harness 要做的事：循环开始前准备好能力索引，Skill 被选中时装入正文。Skill 把方法整理成可分批取用的几层内容，Agent Loop 让它们随任务推进逐步展开；只有目录分层、没有这条循环，几份文件仍然只是一堆彼此分开的材料。</p><h2 id="harness-怎样把-skill-接入这条-loop" tabindex="-1">Harness 怎样把 Skill 接入这条 Loop？ <a class="header-anchor" href="#harness-怎样把-skill-接入这条-loop" aria-label="Permalink to &quot;Harness 怎样把 Skill 接入这条 Loop？&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent Skills 规范把方法组织成三层：名称和描述负责发现，完整 SKILL.md 提供工作方法，</span></span>
<span class="line"><span>references/、scripts/、assets/ 保存较长的资料、程序和模板，为 Agent Loop 准备</span></span></code></pre></div><p>了不同深度的入口。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>以 Codex 为例，它从当前工作目录向仓库根目录查找 .agents/skills/，任务开始时只整</span></span>
<span class="line"><span>理一份含名称、描述和路径的 Skill 列表。模型按描述选择能力，你也可用 $skill-name 指</span></span>
<span class="line"><span>定；Skill 被选中后，Harness 才把完整 SKILL.md 装入任务。</span></span>
<span class="line"><span>同目录里的参考资料和脚本不会自动进入 Context，SKILL.md 要说明什么情况下读取哪份文</span></span></code></pre></div><p>件；模型走到相应步骤，才通过文件读取或命令执行取用，Harness 再把结果带回 AgentLoop。</p><p>初始 Skill 列表本身也有 Context 预算。安装的 Skill 太多时，Codex 会先缩短描述，必要时还</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>会省略一部分 Skill。因此，description 不只是一句介绍，它本身就是入口，决定一项</span></span></code></pre></div><p>Skill 能否被正确发现。</p><p>描述写得太宽泛，比如只写“处理各类问题”，模型在无关任务里也可能误选这项 Skill；写得太窄、漏掉“数据库连接池”这样的关键词，真正的连接池告警到来时它又不会被选中。发现这一步错了，后面的分层再精细也用不上。</p><p>Claude Code 和 OpenCode 也实现了相近的分层，只是发现目录和调用入口不同。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/08/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/08/2.png" alt=""></a></p><p>目录和入口虽不同，三家处理的是同一组问题：先给足以选择能力的信息，选中后装入完整方法，更长的资料则留在 Context 外，直到真正需要。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/08/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/08/3.png" alt=""></a></p><p>随着手册越积越多，真正的问题不再是能不能把方法交给 Agent，而是它能否在需要的那一刻，找到并读到其中正确的那一部分；否则拥有和用不上并没有区别。</p><p>让 Agent 拥有更多方法，不等于把所有手册同时堆给它。有用的设计是先给一份足以选择方向的索引，确认需要再打开正文，走到具体步骤才取用资料和脚本。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AGENTS.md 适合保存相关任务始终要遵守的短规则；Skill 保存只在某类任务中使用的完整方</span></span></code></pre></div><p>法；Skill 内部较长的说明、模板和程序，还可以继续放在独立文件中按需取用。</p><p>渐进披露减少了无关内容对当前判断的干扰，却没有把 Skill 变成必须照做的流程，它的正文仍是供模型理解和选用的工作方法。它和第五讲的上下文压缩也不同：压缩是内容进入Context 之后再裁剪，渐进披露则是一开始只放入口、随任务展开，尽量不让无关内容占用预算。</p><p>下一讲，我们继续来看：当某些动作无论如何都不能越过边界时，Harness 怎样用Sandbox、权限和审批真正限制 Agent 的行动空间。</p><h2 id="课后题" tabindex="-1">课后题 <a class="header-anchor" href="#课后题" aria-label="Permalink to &quot;课后题&quot;">​</a></h2><h3 id="观察题-一项-skill-的三层内容何时出现" tabindex="-1">观察题：一项 Skill 的三层内容何时出现？ <a class="header-anchor" href="#观察题-一项-skill-的三层内容何时出现" aria-label="Permalink to &quot;观察题：一项 Skill 的三层内容何时出现？&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>为一项 Skill 准备简短的 description、主干 SKILL.md、一份参考资料和一个检查脚本。</span></span></code></pre></div><p>先给 Agent 一项与这项 Skill 无关的任务，再提交一项明确匹配描述的任务。</p><p>观察运行记录：模型最初能看到哪些 Skill 信息，完整正文从什么时候开始影响行动，参考资料是否等到对应步骤才被读取，检查脚本的源码和执行结果又分别怎样出现。</p><h3 id="思考题-不用-skill-只用-mcp-能否重做出同样的渐进披露" tabindex="-1">思考题：不用 Skill，只用 MCP，能否重做出同样的渐进披露？ <a class="header-anchor" href="#思考题-不用-skill-只用-mcp-能否重做出同样的渐进披露" aria-label="Permalink to &quot;思考题：不用 Skill，只用 MCP，能否重做出同样的渐进披露？&quot;">​</a></h3><p>假设不再提供原生 Skill，只能接入 MCP Server，但你仍希望模型先看到简短的能力索引，匹配后再取得完整方法，走到具体步骤才读取资料或获得工具。</p><p>MCP 可以提供 Prompts、Resources 和 Tools，却不会替 Host 决定什么时候把哪一项内容交给模型。</p><p>为了重做出刚才的三层加载过程，Host 至少要保存哪些状态，又要在什么时刻完成发现、选择、读取和工具开放？与声明一项 Skill 相比，这套实现多出了哪些工程工作，又换来了哪些更精确的控制？</p><p>期待你在留言区记录想法或疑问。如果这一讲对你有帮助，别忘了分享给身边更多朋友。</p>`,61)])])}const k=a(p,[["render",t]]);export{g as __pageData,k as default};
